def lis_length(nums):
    """
    Returns the length of the longest strictly increasing subsequence.
    Uses O(n log n) algorithm with patience sorting / binary search.
    """
    if not nums:
        return 0

    # tails[i] is the smallest tail of all increasing subsequences of length i+1.
    tails = []

    for num in nums:
        # Binary search for the first element in tails >= num
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        # If left == len(tails), we found a larger element, extend the subsequence
        if left == len(tails):
            tails.append(num)
        else:
            # Otherwise, replace the element at left with num to keep tails sorted and minimal
            tails[left] = num

    return len(tails)
```

