def parse_duration(s: str) -> int:
    """
    Converts a duration string like '1h30m15s', '45m', '2h' or '90s' 
    into the total number of seconds (int).

    Supported units: h (hours), m (minutes), s (seconds).
    The order does not matter.
    """
    total_seconds = 0
    s = s.lower()

    for unit in ['h', 'm', 's']:
        if unit in s:
            # Split by the unit to get the number part
            parts = s.split(unit)
            number_str = parts[0]

            if number_str:
                try:
                    number = int(number_str)
                    if unit == 'h':
                        total_seconds += number * 3600
                    elif unit == 'm':
                        total_seconds += number * 60
                    elif unit == 's':
                        total_seconds += number
                except ValueError:
                    pass

    return total_seconds
